def semver_sort(versions):
    def parse_identifier(ident):
        if ident.isdigit():
            return (0, int(ident))
        else:
            return (1, ident)

    def key_func(v):
        # strip build metadata
        core_and_pre = v.split('+', 1)[0]
        if '-' in core_and_pre:
            core, pre = core_and_pre.split('-', 1)
        else:
            core, pre = core_and_pre, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if pre is None:
            pre_flag = 1
            pre_tuple = ()
        else:
            pre_flag = 0
            idents = pre.split('.')
            pre_tuple = tuple(parse_identifier(i) for i in idents)

        return (major, minor, patch, pre_flag, pre_tuple)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: key_func(pair[1]))
    return [v for _, v in indexed]

